const test = require('node:test');
const assert = require('node:assert/strict');
const { durationLabel } = require('../tour/service.cjs');
test('minutes always occupy two decimal digits', () => {
  for (const [input,expected] of [[65,'1:05'],[0,'0:00'],[9,'0:09'],[10,'0:10'],[59,'0:59'],[60,'1:00'],[1505,'25:05'],[6005,'100:05']]) {
    assert.equal(durationLabel(input),expected);
  }
});

